const data = $json;

const topSources = data.top_sources || [];
const recentErrors = data.recent_errors || [];

const topSourcesText = topSources.length
  ? topSources
      .map(source => `- ${source.lead_source}: ${source.leads_count}`)
      .join('\n')
  : '- No leads in the last 24h';

const recentErrorsText = recentErrors.length
  ? recentErrors
      .map(e => [
        `- Event: ${e.external_id || e.internal_id}`,
        `  Status: ${e.processing_status}`,
        `  Retries: ${e.retry_count || 0}`,
        `  Error: ${e.error_message || 'n/a'}`
      ].join('\n'))
      .join('\n')
  : '- No failed/manual_review events';

let healthStatus = '✅ Healthy';

if (Number(data.manual_review_events) > 0) {
  healthStatus = '🚨 Needs attention';
} else if (Number(data.failed_events) > 0) {
  healthStatus = '⚠️ Degraded';
}

const report = `
📊 LeadOps Daily Monitoring Report

Status: ${healthStatus}

Last 24 hours:
- Total events: ${data.total_events_24h}
- Completed: ${data.completed_events}
- Failed: ${data.failed_events}
- Manual review: ${data.manual_review_events}
- Duplicate leads: ${data.duplicate_lead_events}
- Retrying: ${data.retrying_events}
- Failure rate: ${data.failure_rate_percent || 0}%

Leads:
- New leads: ${data.new_leads_24h}

Top lead sources:
${topSourcesText}

Retries:
- Started: ${data.retries_started_24h}
- Success: ${data.retries_success_24h}
- Failed: ${data.retries_failed_24h}
- Manual review required: ${data.manual_review_required_24h}

Recent problem events:
${recentErrorsText}
`.trim();

return [
  {
    json: {
      report,
      health_status: healthStatus,
      generated_at: new Date().toISOString()
    }
  }
];
